solution.code:
function parseListQuery(query) {
  const errors = [];

  const page = toInteger(query.page);
  if (query.page !== undefined && (page === null || page < 1)) {
    errors.push('page must be an integer of at least 1');
  }

  const pageSize = toInteger(query.pageSize);
  if (query.pageSize !== undefined && (pageSize === null || pageSize < 1 || pageSize > 100)) {
    errors.push('pageSize must be an integer between 1 and 100');
  }

  const status = query.status === undefined ? 'all' : query.status;
  if (status !== 'open' && status !== 'resolved' && status !== 'all') {
    errors.push("status must be 'open', 'resolved' or 'all'");
  }

  if (errors.length > 0) {
    return { ok: false, errors: errors };
  }
  return {
    ok: true,
    value: {
      page: page === null ? 1 : page,
      pageSize: pageSize === null ? 20 : pageSize,
      status: status,
    },
  };
}

function toInteger(raw) {
  if (typeof raw !== 'string' || !/^\d+$/.test(raw)) {
    return null;
  }
  return Number(raw);
}

