app.post('/api/tickets', (req, res) => {
  const result = validateCreateTicket(req.body); // returns { valid, value | errors }
  if (!result.valid) {
    return res.status(400).json({
      error: { code: 'invalid_request', message: 'Check the fields below', details: result.errors },
