solution.code:
function toErrorResponse(error, requestId) {
  const known = {
    validation: { status: 400, code: 'invalid_request' },
    not_found: { status: 404, code: 'not_found' },
    forbidden: { status: 403, code: 'forbidden' },
    conflict: { status: 409, code: 'conflict' },
  };

  const match = error && typeof error === 'object' ? known[error.kind] : undefined;

  if (!match) {
    return {
      status: 500,
      body: {
        error: {
          code: 'internal_error',
          message: 'Something went wrong. Please try again.',
          requestId: requestId,
        },
      },
    };
  }

  const payload = { code: match.code, message: error.message, requestId: requestId };
  if (error.kind === 'validation') {
    payload.details = error.details || [];
  }
  return { status: match.status, body: { error: payload } };
}

